UPDATE inventory inv
SET height = inv.size,
    size = NULL,
    size_std = NULL
FROM m
WHERE inv.is_active AND inv.supplier_id = m.sid AND inv.size = m.sz
  AND inv.height IS NOT NULL
  AND inv.height_std IS NOT DISTINCT FROM m.dstd;

