UPDATE inventory inv
SET caliper = inv.size,
    size = NULL,
    size_std = NULL
FROM m
WHERE inv.is_active AND inv.supplier_id = m.sid AND inv.size = m.sz
  AND inv.caliper IS NOT NULL
  AND inv.caliper_std IS NOT DISTINCT FROM m.dstd;
